namespace Awl { partial class Shell {
 static readonly string[] ComponentColorKeys={"Accent","Panel","Sidebar","PrimaryText","SecondaryText","Borders","Icons"};
 static readonly string[] ComponentColorNames={"Accent","Panel background","Sidebar background","Text — primary","Text — secondary","Borders","Icons"};
 Dictionary<string,string> componentThemeColors=new Dictionary<string,string>();Color componentSidebarColor;Brush componentBorderBrush,componentIconBrush;
 string ComponentColorHex(string key){if(cfg.ComponentColorsCustom){string custom;if(cfg.ComponentColorOverrides!=null&&cfg.ComponentColorOverrides.TryGetValue(key,out custom)&&ValidComponentColor(custom))return custom.ToUpperInvariant();}string value;return componentThemeColors.TryGetValue(key,out value)?value:"#5B9AA0";}
 static bool ValidComponentColor(string value){return value!=null&&Regex.IsMatch(value,"^#[0-9a-fA-F]{6}$");}
 bool ComponentColorApplied(string key){return cfg.ComponentColorsCustom&&cfg.ComponentColorOverrides!=null&&cfg.ComponentColorOverrides.ContainsKey(key)||!cfg.Automatic&&cfg.TemplateComponentColors!=null&&cfg.TemplateComponentColors.ContainsKey(key);}
 Brush ComponentIconBrush(Brush requested){return ComponentColorApplied("Icons")&&(requested==null||Object.ReferenceEquals(requested,ink))?componentIconBrush??requested??ink:requested??ink;}
 void ApplyComponentColors(){
  cfg.ComponentColorOverrides=cfg.ComponentColorOverrides??new Dictionary<string,string>();cfg.TemplateComponentColors=cfg.TemplateComponentColors??new Dictionary<string,string>();
  componentThemeColors=new Dictionary<string,string>{{"Accent",Hex(AccentColor())},{"Panel",Hex(baseColor)},{"Sidebar",Hex(Mix(baseColor,Colors.Black,light?.02:.14))},{"PrimaryText",Hex(((SolidColorBrush)ink).Color)},{"SecondaryText",Hex(((SolidColorBrush)mutedBrush).Color)},{"Borders",Hex(Mix(baseColor,Colors.White,(light?34:28)/255d))},{"Icons",Hex(((SolidColorBrush)ink).Color)}};
  if(!cfg.Automatic)foreach(string key in ComponentColorKeys){string value;if(cfg.TemplateComponentColors.TryGetValue(key,out value)&&ValidComponentColor(value))componentThemeColors[key]=value.ToUpperInvariant();}
  baseColor=Parse(ComponentColorHex("Panel"),baseColor);ink=new SolidColorBrush(Parse(ComponentColorHex("PrimaryText"),Colors.White));mutedBrush=new SolidColorBrush(Parse(ComponentColorHex("SecondaryText"),Colors.Gray));accentBrush=new SolidColorBrush(Parse(ComponentColorHex("Accent"),Colors.Teal));componentSidebarColor=Parse(ComponentColorHex("Sidebar"),baseColor);componentIconBrush=new SolidColorBrush(Parse(ComponentColorHex("Icons"),Colors.White));
  bool borderOverride=cfg.ComponentColorsCustom&&cfg.ComponentColorOverrides.ContainsKey("Borders")||!cfg.Automatic&&cfg.TemplateComponentColors.ContainsKey("Borders");componentBorderBrush=borderOverride?new SolidColorBrush(Parse(ComponentColorHex("Borders"),Colors.Gray)):new SolidColorBrush(Color.FromArgb(light?(byte)34:(byte)28,255,255,255));teal=new SolidColorBrush(baseColor);
  if(cfg.ComponentColorsCustom&&cfg.ComponentColorOverrides.ContainsKey("Panel")||!cfg.Automatic&&cfg.TemplateComponentColors.ContainsKey("Panel"))panelBrush=SurfaceBrush(baseColor,1,false);
 }
 void PreserveComponentOverrides(Preferences next){next.ComponentColorsCustom=cfg.ComponentColorsCustom;next.ComponentColorOverrides=new Dictionary<string,string>(cfg.ComponentColorOverrides??new Dictionary<string,string>());}
 void BakeTemplateComponentColors(Preferences clone){bool custom=clone.ComponentColorsCustom;clone.TemplateComponentColors=ComponentColorKeys.ToDictionary(key=>key,key=>ComponentColorHex(key));clone.ComponentColorOverrides=new Dictionary<string,string>();clone.ComponentColorsCustom=false;if(custom)clone.Automatic=false;clone.DockColor=ComponentColorHex("Panel");clone.IconColor=ComponentColorHex("PrimaryText");}
 void ChangeComponentColor(string key,string value){if(!ComponentColorKeys.Contains(key)||!ValidComponentColor(value))return;cfg.ComponentColorsCustom=true;cfg.ComponentColorOverrides=cfg.ComponentColorOverrides??new Dictionary<string,string>();cfg.ComponentColorOverrides[key]=value.ToUpperInvariant();RefreshComponentColors();}
 void ResetComponentColor(string key){if(cfg.ComponentColorOverrides!=null)cfg.ComponentColorOverrides.Remove(key);RefreshComponentColors();}
 void RefreshComponentColors(){SaveConfig();RefreshTemplateAppearance();if(quickSearchWindow!=null){RefreshWindowBackground(quickSearchWindow,1,false);BuildQuickSearchHeader();RenderQuickSearch();}}
 void ComponentColorsSection(){page.Children.Add(Card("",()=>{
