  var description=Text("On Auto, colors are pulled from your wallpaper. Custom overrides the active template’s colors — switching templates keeps your overrides, on top of the new template.",11.5,mutedBrush);description.LineHeight=14;description.Margin=new Thickness(0,0,0,4);page.Children.Add(description);
