   Action pick=()=>OpenColorPicker(label,ComponentColorHex(key),value=>ChangeComponentColor(key,value));var code=QuickButton(hex,pick,6);code.FontFamily=new FontFamily("Consolas");code.FontSize=10;code.Padding=new Thickness(8,4,8,4);code.Height=23;code.Margin=new Thickness(8,0,0,0);code.ToolTip="Edit "+label+" color";DockPanel.SetDock(code,Dock.Right);row.Children.Add(code);
   var swatch=QuickButton("",pick,8);swatch.Width=26;swatch.Height=26;swatch.Padding=new Thickness(0);swatch.Content=new Border{Width=26,Height=26,CornerRadius=new CornerRadius(8),Background=new SolidColorBrush(Parse(hex,Colors.Teal)),BorderBrush=SoftBorder(),BorderThickness=new Thickness(1)};swatch.Background=Brushes.Transparent;swatch.BorderThickness=new Thickness(0);swatch.BorderBrush=SoftBorder();swatch.Margin=new Thickness(2,0,12,0);swatch.ToolTip="Edit "+label+" · "+hex;System.Windows.Automation.AutomationProperties.SetName(swatch,label+" color "+hex);DockPanel.SetDock(swatch,Dock.Left);row.Children.Add(swatch);row.Children.Add(Text(label,13,ink));page.Children.Add(row);if(i<ComponentColorKeys.Length-1)page.Children.Add(new Border{Height=1,Background=SoftBorder()});
  }
 }));}
 public string ComponentColorsSelfTest(){var original=cfg;var oldPalette=palette;try{cfg=new Preferences{Automatic=true,Mode="Dark",TextColorScheme="Auto"};palette=new List<Swatch>{new Swatch{Hex="#126A82",Coverage=1}};ApplyTheme();string automatic=ComponentColorHex("Accent");cfg.ComponentColorsCustom=true;cfg.ComponentColorOverrides["Accent"]="#FF6600";cfg.ComponentColorOverrides["Sidebar"]="#102030";cfg.ComponentColorOverrides["Icons"]="#FEDCBA";ApplyTheme();if(Hex(AccentColor())!="#FF6600"||Hex(componentSidebarColor)!="#102030"||Hex(((SolidColorBrush)ComponentIconBrush(ink)).Color)!="#FEDCBA")throw new Exception("Overrides were not applied");palette=new List<Swatch>{new Swatch{Hex="#A51265",Coverage=1}};ApplyTheme();if(Hex(AccentColor())!="#FF6600")throw new Exception("Wallpaper change lost override");var next=new Preferences{DockColor="#304050",Automatic=false};PreserveComponentOverrides(next);cfg=next;ApplyTheme();if(Hex(AccentColor())!="#FF6600")throw new Exception("Template change lost override");cfg.ComponentColorOverrides.Remove("Accent");ApplyTheme();if(Hex(AccentColor())=="#FF6600")throw new Exception("Reset did not restore theme");var serializer=new System.Web.Script.Serialization.JavaScriptSerializer();var saved=serializer.Deserialize<Preferences>(serializer.Serialize(cfg));if(saved.ComponentColorOverrides["Sidebar"]!="#102030")throw new Exception("Persistence failed");var clone=serializer.Deserialize<Preferences>(serializer.Serialize(cfg));BakeTemplateComponentColors(clone);if(clone.TemplateComponentColors["Sidebar"]!="#102030"||clone.ComponentColorOverrides.Count!=0)throw new Exception("Template snapshot failed");cfg.ComponentColorsCustom=false;cfg.Automatic=true;ApplyTheme();if(componentThemeColors["Accent"]==automatic)throw new Exception("Wallpaper palette did not update");return "Component colors: live overrides, wallpaper changes, reset, persistence and template layering passed";}catch(Exception error){return "FAILED: "+error.Message;}finally{cfg=original;palette=oldPalette;ApplyTheme();}}
} }
